export interface IamDomainsListQuery {
  /** Inclui os revogados (padrão: false) */
  include_revoked?: boolean;
}

/** Routes tagged `iam · domains`. */
export class IamDomainsResource extends Resource {
  /**
   * Lista os domínios próprios de login do tenant.
   *
   * Cada item traz o registro TXT a publicar e o resultado da última consulta,
   * que é o que o painel precisa para guiar quem configura o DNS.
   *
   * `GET /v1/iam/domains`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  list(query?: IamDomainsListQuery, options?: RequestOptions): Promise<S.IamDomainListDto> {
    return this._http.request({ method: 'GET', path: `/v1/iam/domains`, query, options });
  }

  /**
   * Cadastra um domínio próprio de login.
   *
   * O cadastro nasce pendente, com um token novo para o TXT. Cadastrar de novo
   * um domínio vivo devolve o mesmo cadastro, com o mesmo token: o cliente que
   * repete o pedido não invalida o registro que já publicou.
   *
   * `POST /v1/iam/domains`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  register(body: S.RegisterIamDomainBody, options?: RequestOptions): Promise<S.IamDomainDto> {
    return this._http.request({ method: 'POST', path: `/v1/iam/domains`, body, options });
  }

  /**
   * Revoga o domínio.
   *
   * A linha fica (histórico e trilha); o domínio deixa de identificar o tenant
   * e pode ser cadastrado de novo, com outro token.
   *
   * `DELETE /v1/iam/domains/{id}`
   *
   * @param id ID Snowflake do domínio
   * @param options Per-call overrides.
   */
  revoke(id: string, options?: RequestOptions): Promise<void> {
    return this._http.request({ method: 'DELETE', path: `/v1/iam/domains/${seg(id)}`, responseType: 'void', options });
  }

  /**
   * Entrada só pelo domínio próprio.
   *
   * Ligada, o hub não abre sessão nesse tenant: a conta aparece na escolha de
   * empresa só como link para o domínio. Se o domínio cair depois, o hub volta
   * a aceitar sozinho, para ninguém ficar sem porta.
   *
   * `PUT /v1/iam/domains/login-domain-only`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setLoginDomainOnly(body: S.LoginDomainOnlyBody, options?: RequestOptions): Promise<S.LoginDomainOnlyDto> {
    return this._http.request({ method: 'PUT', path: `/v1/iam/domains/login-domain-only`, body, options });
  }

  /**
   * Marca o domínio como primário.
   *
   * Só domínio verificado e vivo pode ser primário. A troca é atômica: o
   * tenant nunca fica com dois primários.
   *
   * `POST /v1/iam/domains/{id}/primary`
   *
   * @param id ID Snowflake do domínio
   * @param options Per-call overrides.
   */
  setPrimary(id: string, options?: RequestOptions): Promise<S.IamDomainDto> {
    return this._http.request({ method: 'POST', path: `/v1/iam/domains/${seg(id)}/primary`, options });
  }

  /**
   * Consulta o TXT do desafio agora.
   *
   * Não achar o registro **não** é erro: a resposta é 200 com `outcome`
   * dizendo o que aconteceu e `found` com o que está publicado. Consulta que
   * falha nunca rebaixa um domínio já verificado.
   *
   * `POST /v1/iam/domains/{id}/verify`
   *
   * @param id ID Snowflake do domínio
   * @param options Per-call overrides.
   */
  verify(id: string, options?: RequestOptions): Promise<S.IamDomainVerifyDto> {
    return this._http.request({ method: 'POST', path: `/v1/iam/domains/${seg(id)}/verify`, options });
  }
}

